SELECT *
FROM customers.customers

# Find total revenue generated by each product.

select 
    p.category,
    sum(i.quantity * i.unit_price) as ttl_revenue
from sales.order_items i
join products.products p 
    on p.prod_id = i.prod_id
group by p.category;

# Find top 5 customers based on total purchase amount

SELECT 
    o.cust_id,
    SUM(o.total_amount) AS ttl_purchase
FROM sales.orders o
GROUP BY o.cust_id
ORDER BY ttl_purchase DESC
LIMIT 5;


-- Q3 – Monthly sales trend (last 12 months)

select 
	date_trunc('month', order_date) as month,
	sum(total_amount) as monthly_revenue
from sales.orders
where order_date >= current_date - interval '12 months'
group by date_trunc('month', order_date)
order by month;

-- Q4 – Region with highest average order value

select * from sales.orders
select * from customers.customers


# Method 1

SELECT
	c.region_name,
	avg(o.total_amount) avg_order_value
	from sales.orders o
	join customers.customers c
	on c.cust_id = o.cust_id
	group by c.region_name
	order by avg_order_value desc
	limit 1;

# Method 2

# Using Cte and window ( when all regions tied for highest avg order value )


with region_avg as (
     select 
	 	c.region_name,
		round(avg(o.total_amount), 2) as avg_order_value
	from sales.orders o
	join customers.customers c
		on c.cust_id = o.cust_id
	group by c.region_name
)all regions tied for highest avg order value

select region_name,
		avg_order_value,
		dense_rank() over (
		partition by region_name
	order by avg_order_value desc 
	from region_avg
) as rnk

where rnk = 1;


WITH region_avg AS (
    SELECT
        c.region_name,
        AVG(o.total_amount) AS avg_order_value
    FROM sales.orders o
    JOIN customers.customers c
        ON c.cust_id = o.cust_id
    GROUP BY c.region_name
),
ranked AS (
    SELECT 
        region_name,
        avg_order_value,
        DENSE_RANK() OVER (ORDER BY avg_order_value DESC) AS rnk
    FROM region_avg
)

SELECT *
FROM ranked
WHERE rnk = 1;